CREATE TABLE items (id INT PRIMARY KEY, old_label TEXT);
CREATE OR REPLACE TABLE items (id INT PRIMARY KEY, label TEXT NOT NULL, price DECIMAL(10, 2));
CREATE OR REPLACE TABLE item_copies LIKE items;
CREATE OR REPLACE TABLE item_totals AS SELECT id, price FROM items;
CREATE OR REPLACE INDEX items_label ON items (label(10));
CREATE OR REPLACE DATABASE archive;
CREATE OR REPLACE TRIGGER items_touch BEFORE INSERT ON items FOR EACH ROW SET NEW.label = 'x';
